-- ===== INDEXES =====
CREATE INDEX idx_admin_alerts_unread ON public.admin_alerts USING btree (is_read, created_at DESC);
CREATE INDEX idx_chat_messages_thread_id ON public.chat_messages USING btree (thread_id);
CREATE INDEX idx_chat_threads_opponent ON public.chat_threads USING btree (opponent_team_id) WHERE (opponent_team_id IS NOT NULL);
CREATE INDEX idx_chat_threads_player ON public.chat_threads USING btree (player_id) WHERE (player_id IS NOT NULL);
CREATE INDEX idx_chat_threads_team_activity ON public.chat_threads USING btree (team_id, last_message_at DESC NULLS LAST) WHERE (archived = false);
CREATE INDEX idx_chat_threads_team_id ON public.chat_threads USING btree (team_id);
CREATE INDEX idx_checkins_coach ON public.checkins USING btree (coach_id);
CREATE INDEX idx_checkins_created ON public.checkins USING btree (created_at DESC);
CREATE INDEX idx_checkins_prescription ON public.checkins USING btree (prescription_id);
