-- ===== VIEWS =====
CREATE OR REPLACE VIEW public.admin_daily_active_users WITH (security_invoker = on) AS
 SELECT date(created_at) AS day,
    count(DISTINCT user_id) AS unique_users,
    count(*) AS total_events
   FROM user_events
  WHERE created_at > (now() - '30 days'::interval)
  GROUP BY (date(created_at))
  ORDER BY (date(created_at)) DESC;
CREATE OR REPLACE VIEW public.admin_feature_usage WITH (security_invoker = on) AS
 SELECT event_name,
    count(*) AS usage_count,
    count(DISTINCT user_id) AS unique_users
   FROM user_events
  WHERE created_at > (now() - '30 days'::interval) AND event_type = 'feature_use'::text
  GROUP BY event_name
  ORDER BY (count(*)) DESC;
CREATE OR REPLACE VIEW public.admin_user_activity WITH (security_invoker = on) AS
 SELECT user_id,
    display_name,
    is_subscribed,
    subscription_tier,
    stripe_customer_id,
    created_at AS signup_date,
    ( SELECT max(ue.created_at) AS max
           FROM user_events ue
          WHERE ue.user_id = c.user_id) AS last_active,
    ( SELECT count(*) AS count
           FROM user_events ue
          WHERE ue.user_id = c.user_id AND ue.created_at > (now() - '7 days'::interval)) AS events_last_7d,
    ( SELECT count(*) AS count
           FROM user_events ue
          WHERE ue.user_id = c.user_id AND ue.created_at > (now() - '30 days'::interval)) AS events_last_30d,
    ( SELECT count(*) AS count
           FROM user_events ue
          WHERE ue.user_id = c.user_id AND ue.event_name = 'chat_message'::text) AS total_chats,
    ( SELECT count(*) AS count
           FROM user_events ue
          WHERE ue.user_id = c.user_id AND ue.event_name = 'practice_plan_created'::text) AS total_plans,
    ( SELECT count(*) AS count
           FROM user_events ue
          WHERE ue.user_id = c.user_id AND ue.event_name = 'game_logged'::text) AS total_games,
    ( SELECT count(*) AS count
           FROM user_events ue
          WHERE ue.user_id = c.user_id AND ue.event_name = 'lineup_generated'::text) AS total_lineups,
    ( SELECT count(*) AS count
           FROM user_events ue
          WHERE ue.user_id = c.user_id AND ue.event_name = 'swing_analysis'::text) AS total_analyses,
    ( SELECT count(DISTINCT date(ue.created_at)) AS count
           FROM user_events ue
          WHERE ue.user_id = c.user_id AND ue.created_at > (now() - '30 days'::interval)) AS active_days_last_30d
   FROM coaches c
  ORDER BY (( SELECT max(ue.created_at) AS max
           FROM user_events ue
          WHERE ue.user_id = c.user_id)) DESC NULLS LAST;
CREATE OR REPLACE VIEW public.player_season_batting WITH (security_invoker = on) AS
 SELECT tp.id AS team_player_id,
    tp.player_id,
    tp.team_id,
    p.name AS player_name,
    p.jersey_number,
    count(DISTINCT pgs.game_id) AS games_played,
    COALESCE(sum(pgs.at_bats), 0::bigint) AS total_ab,
    COALESCE(sum(pgs.hits), 0::bigint) AS total_hits,
    COALESCE(sum(pgs.singles), 0::bigint) AS total_singles,
    COALESCE(sum(pgs.doubles), 0::bigint) AS total_doubles,
    COALESCE(sum(pgs.triples), 0::bigint) AS total_triples,
    COALESCE(sum(pgs.home_runs), 0::bigint) AS total_hr,
    COALESCE(sum(pgs.rbi), 0::bigint) AS total_rbi,
    COALESCE(sum(pgs.runs), 0::bigint) AS total_runs,
    COALESCE(sum(pgs.walks), 0::bigint) AS total_walks,
    COALESCE(sum(pgs.strikeouts), 0::bigint) AS total_strikeouts,
    COALESCE(sum(pgs.hbp), 0::bigint) AS total_hbp,
    COALESCE(sum(pgs.sac), 0::bigint) AS total_sac,
    COALESCE(sum(pgs.stolen_bases), 0::bigint) AS total_sb,
    COALESCE(sum(pgs.caught_stealing), 0::bigint) AS total_cs,
        CASE
            WHEN COALESCE(sum(pgs.at_bats), 0::bigint) > 0 THEN round(COALESCE(sum(pgs.hits), 0::bigint)::numeric / COALESCE(sum(pgs.at_bats), 0::bigint)::numeric, 3)
            ELSE 0::numeric
        END AS batting_avg,
        CASE
            WHEN (COALESCE(sum(pgs.at_bats), 0::bigint) + COALESCE(sum(pgs.walks), 0::bigint) + COALESCE(sum(pgs.hbp), 0::bigint) + COALESCE(sum(pgs.sac), 0::bigint)) > 0 THEN round((COALESCE(sum(pgs.hits), 0::bigint) + COALESCE(sum(pgs.walks), 0::bigint) + COALESCE(sum(pgs.hbp), 0::bigint))::numeric / (COALESCE(sum(pgs.at_bats), 0::bigint) + COALESCE(sum(pgs.walks), 0::bigint) + COALESCE(sum(pgs.hbp), 0::bigint) + COALESCE(sum(pgs.sac), 0::bigint))::numeric, 3)
            ELSE 0::numeric
        END AS obp,
        CASE
            WHEN COALESCE(sum(pgs.at_bats), 0::bigint) > 0 THEN round((COALESCE(sum(pgs.singles), 0::bigint) + COALESCE(sum(pgs.doubles), 0::bigint) * 2 + COALESCE(sum(pgs.triples), 0::bigint) * 3 + COALESCE(sum(pgs.home_runs), 0::bigint) * 4)::numeric / COALESCE(sum(pgs.at_bats), 0::bigint)::numeric, 3)
            ELSE 0::numeric
        END AS slg,
    COALESCE(sum(pgs.putouts), 0::bigint) AS total_putouts,
    COALESCE(sum(pgs.assists), 0::bigint) AS total_assists,
    COALESCE(sum(pgs.errors), 0::bigint) AS total_errors
   FROM team_players tp
     JOIN players p ON p.id = tp.player_id
     LEFT JOIN player_game_stats pgs ON pgs.team_player_id = tp.id
  GROUP BY tp.id, tp.player_id, tp.team_id, p.name, p.jersey_number;
-- ===== FUNCTIONS =====
CREATE OR REPLACE FUNCTION public.bc_claim_league_seat(p_invitation_id uuid, p_league_id uuid)
 RETURNS TABLE(claimed boolean, reason text, seats_used integer, coach_limit integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_limit    INT;
  v_used     INT;
  v_status   TEXT;
  v_licensed BOOLEAN;
BEGIN
  -- Serialise every concurrent claim for this league behind the licence row.
  -- Ordered and limited so the lock target is deterministic when a league has
  -- more than one live licence.
  SELECT l.coach_limit, TRUE
    INTO v_limit, v_licensed
  FROM league_licenses l
  WHERE l.league_id = p_league_id
    AND l.status IN ('trial', 'active')
    AND (l.starts_at IS NULL OR l.starts_at <= NOW())
    AND (l.ends_at   IS NULL OR l.ends_at   >  NOW())
  ORDER BY l.created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT COALESCE(v_licensed, FALSE) THEN
    RETURN QUERY SELECT FALSE, 'league_unlicensed'::TEXT, 0, NULL::INT;
    RETURN;
  END IF;

  -- Re-read the invitation under the lock. Its status may have changed since
  -- the route validated it.
  SELECT i.status INTO v_status
  FROM league_invitations i
  WHERE i.id = p_invitation_id AND i.league_id = p_league_id
  FOR UPDATE;

  IF v_status IS NULL THEN
    RETURN QUERY SELECT FALSE, 'not_found'::TEXT, 0, v_limit;
    RETURN;
  END IF;

  IF v_status <> 'pending' THEN
    -- 'accepted' is the common case and means somebody got here first — which
    -- is usually the same person clicking twice.
    RETURN QUERY SELECT FALSE, ('invitation_' || v_status)::TEXT, 0, v_limit;
    RETURN;
  END IF;

  SELECT count(*)::INT INTO v_used
  FROM league_invitations i
  WHERE i.league_id = p_league_id AND i.status = 'accepted';

  IF v_limit IS NOT NULL AND v_used >= v_limit THEN
    RETURN QUERY SELECT FALSE, 'coach_limit_reached'::TEXT, v_used, v_limit;
    RETURN;
  END IF;

  UPDATE league_invitations
  SET status = 'accepted', accepted_at = NOW()
  WHERE id = p_invitation_id AND status = 'pending';

  RETURN QUERY SELECT TRUE, NULL::TEXT, v_used + 1, v_limit;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.bc_coach_at_least(p_coach uuid, p_min text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT
    EXISTS (SELECT 1 FROM coaches c WHERE c.id = p_coach AND c.user_id = auth.uid())
    OR EXISTS (
      SELECT 1
      FROM teams t
      JOIN team_members tm ON tm.team_id = t.id
      WHERE t.coach_id = p_coach
        AND tm.user_id = auth.uid()
        AND bc_rank(tm.role) >= bc_rank(p_min)
    );
$function$
;
CREATE OR REPLACE FUNCTION public.bc_game_at_least(p_game uuid, p_min text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM games g
    WHERE g.id = p_game AND bc_team_at_least(g.team_id, p_min)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.bc_in_league_team(p_league uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT p_league IS NOT NULL
     AND auth.uid() IS NOT NULL
     AND (
       EXISTS (
         SELECT 1 FROM teams t
         JOIN coaches c ON c.id = t.coach_id
         WHERE t.league_id = p_league AND c.user_id = auth.uid()
       )
       OR EXISTS (
         SELECT 1 FROM teams t
         JOIN team_members tm ON tm.team_id = t.id
         WHERE t.league_id = p_league AND tm.user_id = auth.uid()
       )
     );
$function$
;
CREATE OR REPLACE FUNCTION public.bc_league_at_least(p_league uuid, p_min text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT p_league IS NOT NULL
     AND auth.uid() IS NOT NULL
     AND bc_league_rank(bc_league_role(p_league)) >= bc_league_rank(p_min);
$function$
;
CREATE OR REPLACE FUNCTION public.bc_league_rank(p_role text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p_role
    WHEN 'owner'             THEN 4
    WHEN 'commissioner'      THEN 3
    WHEN 'admin'             THEN 2
    WHEN 'coaching_director' THEN 1
    -- Reserved. Ranks lowest so that anything gated above it stays shut until
    -- Phase 1 of division scoping actually exists.
    WHEN 'division_admin'    THEN 0
    ELSE -1
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.bc_league_role(p_league uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT lm.role
  FROM league_members lm
  WHERE lm.league_id = p_league
    AND lm.user_id = auth.uid()
  LIMIT 1;
$function$
;
CREATE OR REPLACE FUNCTION public.bc_opponent_team_at_least(p_opp uuid, p_min text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM opponent_teams ot
    WHERE ot.id = p_opp AND bc_coach_at_least(ot.coach_id, p_min)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.bc_rank(p_role text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p_role
    WHEN 'owner' THEN 3
    WHEN 'admin' THEN 2
    WHEN 'contributor' THEN 1
    WHEN 'viewer' THEN 0
    ELSE -1
  END;
$function$
;
CREATE OR REPLACE FUNCTION public.bc_release_league_seat(p_invitation_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_rows INT;
BEGIN
  UPDATE league_invitations
  SET status = 'pending', accepted_at = NULL
  WHERE id = p_invitation_id AND status = 'accepted';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows > 0;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.bc_team_at_least(p_team uuid, p_min text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT bc_rank(bc_team_role(p_team)) >= bc_rank(p_min);
$function$
;
CREATE OR REPLACE FUNCTION public.bc_team_player_at_least(p_team_player uuid, p_min text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM team_players tp
    WHERE tp.id = p_team_player AND bc_team_at_least(tp.team_id, p_min)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.bc_team_role(p_team uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE
  v_role TEXT;
BEGIN
  IF p_team IS NULL OR auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;

  -- The owner, by way of their coach row.
  SELECT 'owner' INTO v_role
  FROM teams t
  JOIN coaches c ON c.id = t.coach_id
  WHERE t.id = p_team AND c.user_id = auth.uid();
  IF v_role IS NOT NULL THEN
    RETURN v_role;
  END IF;

  SELECT tm.role INTO v_role
  FROM team_members tm
  WHERE tm.team_id = p_team AND tm.user_id = auth.uid()
  LIMIT 1;

  RETURN v_role;
END;
$function$
;
