CREATE OR REPLACE FUNCTION public.calc_batting_avg(total_hits integer, total_abs integer)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
  IF total_abs IS NULL OR total_abs = 0 THEN
    RETURN 0;
  END IF;
  RETURN ROUND(total_hits::DECIMAL / total_abs::DECIMAL, 3);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.extract_youtube_id(url text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
  -- Handle various YouTube URL formats
  IF url IS NULL THEN RETURN NULL; END IF;
  
  -- youtube.com/watch?v=VIDEO_ID
  IF url LIKE '%watch?v=%' THEN
    RETURN substring(url from 'watch\?v=([a-zA-Z0-9_-]+)');
  END IF;
  
  -- youtu.be/VIDEO_ID
  IF url LIKE '%youtu.be/%' THEN
    RETURN substring(url from 'youtu\.be/([a-zA-Z0-9_-]+)');
  END IF;
  
  -- youtube.com/shorts/VIDEO_ID
  IF url LIKE '%/shorts/%' THEN
    RETURN substring(url from '/shorts/([a-zA-Z0-9_-]+)');
  END IF;
  
  RETURN NULL;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.game_notes_to_observation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_coach_id UUID;
  v_team_id  UUID;
  v_date     DATE;
BEGIN
  SELECT g.team_id, t.coach_id, g.game_date
    INTO v_team_id, v_coach_id, v_date
  FROM games g
  JOIN teams t ON t.id = g.team_id
  WHERE g.id = NEW.game_id;

  IF v_coach_id IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO observations (
    coach_id, player_id, team_id, prompt_key, body, observed_on, source_game_note_id
  ) VALUES (
    v_coach_id,
    NEW.player_id,
    v_team_id,
    'in_game_' || COALESCE(NEW.note_type, 'general'),
    NEW.note,
    COALESCE(v_date, CURRENT_DATE),
    NEW.id
  )
  ON CONFLICT (source_game_note_id) WHERE source_game_note_id IS NOT NULL
  DO UPDATE
    SET body = EXCLUDED.body,
        prompt_key = EXCLUDED.prompt_key;

  RETURN NEW;
END;
$function$
;
