CREATE OR REPLACE FUNCTION public.get_user_team_role(p_team_id uuid, p_user_id uuid)
 RETURNS character varying
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_is_owner BOOLEAN;
  v_member_role VARCHAR;
BEGIN
  -- Check if user is team owner
  SELECT EXISTS(
    SELECT 1 FROM teams t
    JOIN coaches c ON t.coach_id = c.id
    WHERE t.id = p_team_id AND c.user_id = p_user_id
  ) INTO v_is_owner;
  
  IF v_is_owner THEN
    RETURN 'owner';
  END IF;
  
  -- Get member role
  SELECT role INTO v_member_role
  FROM team_members
  WHERE team_id = p_team_id AND user_id = p_user_id;
  
  RETURN COALESCE(v_member_role, NULL);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  INSERT INTO public.coaches (user_id, display_name)
  VALUES (new.id, COALESCE(new.raw_user_meta_data->>'display_name', new.email))
  ON CONFLICT (user_id) DO NOTHING;
  RETURN new;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.is_team_member(p_team_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM team_members 
    WHERE team_id = p_team_id AND user_id = auth.uid()
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.is_team_owner_or_member(p_team_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  -- Check if user is a member
  IF EXISTS (SELECT 1 FROM team_members WHERE team_id = p_team_id AND user_id = auth.uid()) THEN
    RETURN TRUE;
  END IF;
  
  -- Check if user owns the team
  IF EXISTS (
    SELECT 1 FROM teams t
    JOIN coaches c ON t.coach_id = c.id
    WHERE t.id = p_team_id AND c.user_id = auth.uid()
  ) THEN
    RETURN TRUE;
  END IF;
  
  RETURN FALSE;
END;
$function$
;
