CREATE OR REPLACE FUNCTION public.mark_opponent_analysis_stale()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_opponent UUID;
BEGIN
  v_opponent := COALESCE(NEW.opponent_team_id, OLD.opponent_team_id);
  IF v_opponent IS NOT NULL THEN UPDATE opponent_teams SET analysis_stale = TRUE WHERE id = v_opponent; END IF;
  RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.mark_opponent_analysis_stale_by_player()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_opponent UUID;
BEGIN
  SELECT opponent_team_id INTO v_opponent FROM opponent_players
  WHERE id = COALESCE(NEW.opponent_player_id, OLD.opponent_player_id);
  IF v_opponent IS NOT NULL THEN UPDATE opponent_teams SET analysis_stale = TRUE WHERE id = v_opponent; END IF;
  RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.parse_age_range(age_text text)
 RETURNS TABLE(min_age integer, max_age integer)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
BEGIN
  IF age_text IS NULL OR age_text = '' THEN
    RETURN QUERY SELECT NULL::INT, NULL::INT;
    RETURN;
  END IF;
  
  -- Handle "6-10", "9-12", etc.
  IF age_text ~ '^\d+-\d+$' THEN
    RETURN QUERY SELECT 
      substring(age_text from '^(\d+)')::INT,
      substring(age_text from '-(\d+)$')::INT;
    RETURN;
  END IF;
  
  -- Handle single age like "8"
  IF age_text ~ '^\d+$' THEN
    RETURN QUERY SELECT age_text::INT, age_text::INT;
    RETURN;
  END IF;
  
  RETURN QUERY SELECT NULL::INT, NULL::INT;
END;
$function$
;
