CREATE OR REPLACE FUNCTION public.user_has_team_permission(p_team_id uuid, p_user_id uuid, p_required_role character varying DEFAULT 'viewer'::character varying)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_is_owner BOOLEAN;
  v_member_role VARCHAR;
BEGIN
  -- Check if user is team owner
  SELECT EXISTS(
    SELECT 1 FROM teams t
    JOIN coaches c ON t.coach_id = c.id
    WHERE t.id = p_team_id AND c.user_id = p_user_id
  ) INTO v_is_owner;
  
  IF v_is_owner THEN
    RETURN TRUE;
  END IF;
  
  -- Check member role
  SELECT role INTO v_member_role
  FROM team_members
  WHERE team_id = p_team_id AND user_id = p_user_id;
  
  IF v_member_role IS NULL THEN
    RETURN FALSE;
  END IF;
  
  -- Check if role meets requirement
  IF p_required_role = 'viewer' THEN
    RETURN TRUE;
  ELSIF p_required_role = 'contributor' THEN
    RETURN v_member_role IN ('contributor', 'admin');
  ELSIF p_required_role = 'admin' THEN
    RETURN v_member_role = 'admin';
  END IF;
  
  RETURN FALSE;
END;
$function$
;
