-- ===== POLICIES =====
CREATE POLICY "Coaches can create chat messages" ON public.chat_messages FOR INSERT TO public WITH CHECK (((thread_id IN ( SELECT chat_threads.id
   FROM chat_threads
  WHERE (chat_threads.team_id IN ( SELECT teams.id
           FROM teams
          WHERE (teams.coach_id IN ( SELECT coaches.id
                   FROM coaches
                  WHERE (coaches.user_id = auth.uid()))))))) OR (thread_id IN ( SELECT chat_threads.id
   FROM chat_threads
  WHERE (chat_threads.team_id IN ( SELECT team_members.team_id
           FROM team_members
          WHERE (team_members.user_id = auth.uid())))))));
CREATE POLICY "Coaches can delete chat messages" ON public.chat_messages FOR DELETE TO public USING (((thread_id IN ( SELECT chat_threads.id
   FROM chat_threads
  WHERE (chat_threads.team_id IN ( SELECT teams.id
           FROM teams
          WHERE (teams.coach_id IN ( SELECT coaches.id
                   FROM coaches
                  WHERE (coaches.user_id = auth.uid()))))))) OR (thread_id IN ( SELECT chat_threads.id
   FROM chat_threads
  WHERE (chat_threads.team_id IN ( SELECT team_members.team_id
           FROM team_members
          WHERE (team_members.user_id = auth.uid())))))));
CREATE POLICY "Coaches can view their team chat messages" ON public.chat_messages FOR SELECT TO public USING (((thread_id IN ( SELECT chat_threads.id
   FROM chat_threads
  WHERE (chat_threads.team_id IN ( SELECT teams.id
           FROM teams
          WHERE (teams.coach_id IN ( SELECT coaches.id
                   FROM coaches
                  WHERE (coaches.user_id = auth.uid()))))))) OR (thread_id IN ( SELECT chat_threads.id
   FROM chat_threads
  WHERE (chat_threads.team_id IN ( SELECT team_members.team_id
           FROM team_members
          WHERE (team_members.user_id = auth.uid())))))));
CREATE POLICY bc_del_chat_messages ON public.chat_messages FOR DELETE TO public USING (bc_thread_at_least(thread_id, 'record'::text));
CREATE POLICY bc_ins_chat_messages ON public.chat_messages FOR INSERT TO public WITH CHECK (bc_thread_at_least(thread_id, 'record'::text));
CREATE POLICY bc_read_chat_messages ON public.chat_messages FOR SELECT TO public USING (bc_thread_at_least(thread_id, 'viewer'::text));
CREATE POLICY bc_upd_chat_messages ON public.chat_messages FOR UPDATE TO public USING (bc_thread_at_least(thread_id, 'record'::text));
CREATE POLICY "Coaches can create chat threads" ON public.chat_threads FOR INSERT TO public WITH CHECK (((team_id IN ( SELECT teams.id
   FROM teams
  WHERE (teams.coach_id IN ( SELECT coaches.id
           FROM coaches
          WHERE (coaches.user_id = auth.uid()))))) OR (team_id IN ( SELECT team_members.team_id
   FROM team_members
  WHERE (team_members.user_id = auth.uid())))));
CREATE POLICY "Coaches can view their team chat threads" ON public.chat_threads FOR SELECT TO public USING (((team_id IN ( SELECT teams.id
   FROM teams
  WHERE (teams.coach_id IN ( SELECT coaches.id
           FROM coaches
          WHERE (coaches.user_id = auth.uid()))))) OR (team_id IN ( SELECT team_members.team_id
   FROM team_members
  WHERE (team_members.user_id = auth.uid())))));
CREATE POLICY bc_del_chat_threads ON public.chat_threads FOR DELETE TO public USING (bc_team_at_least(team_id, 'record'::text));
CREATE POLICY bc_ins_chat_threads ON public.chat_threads FOR INSERT TO public WITH CHECK (bc_team_at_least(team_id, 'record'::text));
CREATE POLICY bc_read_chat_threads ON public.chat_threads FOR SELECT TO public USING (bc_team_at_least(team_id, 'viewer'::text));
CREATE POLICY bc_upd_chat_threads ON public.chat_threads FOR UPDATE TO public USING (bc_team_at_least(team_id, 'record'::text));
CREATE POLICY "Coaches can manage own checkins" ON public.checkins FOR ALL TO public USING ((coach_id IN ( SELECT coaches.id
   FROM coaches
  WHERE (coaches.user_id = auth.uid()))));
